import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), canvas=$('#world');
const ui={health:$('#health-fill'),energy:$('#energy-fill'),food:$('#food-fill'),xp:$('#xp-fill'),level:$('#level'),healthText:$('#health-text'),energyText:$('#energy-text'),foodText:$('#food-text'),xpText:$('#xp-text'),rep:$('#rep'),toast:$('#toast'),modal:$('#modal'),backdrop:$('#modal-backdrop'),interaction:$('#interaction'),interactionText:$('#interaction-text'),hint:$('#nearby-hint'),clock:$('#clock'),region:$('#region-name'),questTitle:$('#quest-title'),questDesc:$('#quest-description'),questBar:$('#quest-progress'),questLabel:$('#quest-progress-label'),flash:$('#screen-flash'),threat:$('#threat'),threatCount:$('#threat-count'),medkits:$('#medkit-count'),coords:$('#coords')};
let scene,camera,renderer,clock3,player,world,dayLight,ambient,moonLight,playerModel,weapon,characterParts=[],keys={},enemies=[],particles=[],pickups=[],npcs=[],structures=[],abilityCooldown={q:0,e:0,r:0,c:0},modalOpen=false,nearby=null,questStage=0,questProgress=0,attackTimer=0,damageFlash=0,worldTime=0,camYaw=0,camPitch=.32,dragging=false,prevPointer={x:0,y:0},saveTimer=0,toastTimer=0;
const state={x:0,z:10,health:100,maxHealth:100,energy:100,maxEnergy:100,food:84,xp:0,level:1,rep:0,medkits:2,amber:0,shards:0,herbs:1,ore:0,weapon:'Fio de Âmbar',kills:0,found:0,decision:'',inventory:{'Fragmento âmbar':2,'Fibra de névoa':1,'Erva-luz':1},seen:{},anchorUnlocked:false,arcUnlocked:false};
const V=(x,y,z)=>new THREE.Vector3(x,y,z), mat=(color,rough=.8,emissive=0x000000,intensity=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,emissive,emissiveIntensity:intensity});
const mats={ground:mat(0x687263),dark:mat(0x1c2929),stone:mat(0x4b5750),pale:mat(0xa6a08b),mint:mat(0x92e5cc,.3,0x52d9b2,.8),amber:mat(0xe4b978,.32,0xc17a31,.6),rust:mat(0x854d40),enemy:mat(0x333e3e),eye:mat(0xe98b72,.3,0xf34f30,2),npc:mat(0x779985),cloth:mat(0x39464a),player:mat(0x263e40),skin:mat(0xb78d70),black:mat(0x111a1d)};
function makeMesh(geo,material,parent,pos=[0,0,0],rot=[0,0,0]){const m=new THREE.Mesh(geo,material);m.position.set(...pos);m.rotation.set(...rot);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function box(parent,pos,scale,material,rot=[0,0,0]){return makeMesh(new THREE.BoxGeometry(...scale),material,parent,pos,rot)}
function orb(parent,pos,scale,material){return makeMesh(new THREE.IcosahedronGeometry(1,1),material,parent,pos).scale.set(...scale)}
function group(parent,pos=[0,0,0]){const g=new THREE.Group();g.position.set(...pos);parent.add(g);return g}
function makeTerrain(){const n=130,size=280,geo=new THREE.PlaneGeometry(size,size,n,n);geo.rotateX(-Math.PI/2);const p=geo.attributes.position,colors=[];for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i),ridge=Math.sin(x*.042+Math.cos(z*.035)*2)*1.6+Math.cos(z*.052-x*.014)*1.3, hummock=Math.sin(x*.12)*Math.cos(z*.09)*.75, h=ridge+hummock+Math.sin((x+z)*.24)*.17;p.setY(i,h);const c=new THREE.Color(h<-.2?0x59645b:h<1.6?0x737568:0x817b69);if(Math.sin(x*.62+z*.44)>0.88)c.lerp(new THREE.Color(0x4b5c53),.52);colors.push(c.r,c.g,c.b)}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const m=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));m.receiveShadow=true;scene.add(m);world.terrain=geo}
function heightAt(x,z){return Math.sin(x*.042+Math.cos(z*.035)*2)*1.6+Math.cos(z*.052-x*.014)*1.3+Math.sin(x*.12)*Math.cos(z*.09)*.75+Math.sin((x+z)*.24)*.17}
function addRock(x,z,s=1){const g=group(scene,[x,heightAt(x,z)-.1,z]);const rock=makeMesh(new THREE.DodecahedronGeometry(s,0),mats.stone,g,[0,s*.48,0],[Math.random(),Math.random(),Math.random()]);rock.scale.set(.9,1.1,.8);if(Math.random()<.48){const crystal=makeMesh(new THREE.OctahedronGeometry(s*.24),mats.mint,g,[s*.18,s*.85,0],[.2,0,.4]);crystal.scale.y=1.8}return g}
function buildTower(x,z){const g=group(scene,[x,heightAt(x,z),z]);for(let i=0;i<5;i++){const a=i*Math.PI*2/5,rad=3.1;box(g,[Math.cos(a)*rad,2.4+Math.random(),Math.sin(a)*rad],[1.5,5+Math.random()*2,1.4],i%2?mats.stone:mats.dark,[0,Math.random()*.4,Math.random()*.2]);}const ring=makeMesh(new THREE.TorusGeometry(3.2,.22,8,32),mats.amber,g,[0,4.6,0],[Math.PI/2,0,0]);const core=makeMesh(new THREE.OctahedronGeometry(1.05),mats.mint,g,[0,4.4,0]);core.userData.pulse=true;for(let i=0;i<7;i++){const a=i*Math.PI*2/7;box(g,[Math.cos(a)*5,Math.random()*2+.7,Math.sin(a)*5],[.4,1.5+Math.random()*2,.4],mats.rust,[Math.random(),a,Math.random()])}g.userData={type:'objective'};return g}
function buildRuins(){for(let i=0;i<16;i++){const a=i*2.39,r=34+(i%5)*8,x=Math.cos(a)*r,z=Math.sin(a)*r;const g=group(scene,[x,heightAt(x,z),z]);if(i%3===0){box(g,[0,2,0],[5,4,4],mats.dark,[0,a*.3,.05]);box(g,[.4,4.1,-.1],[2.5,.3,4],mats.stone,[0,a*.3,.05]);for(let j=0;j<3;j++)box(g,[-1.2+j*1.25,1.3,2.03],[.48,1.9,.15],mats.rust)}else{for(let j=0;j<2+(i%3);j++){const xx=(j-(i%3)/2)*1.9;box(g,[xx,1.3,0],[.9,2.8+Math.random()*2,.9],mats.stone,[0,Math.random()*.3,(Math.random()-.5)*.22]);box(g,[xx,3.2,0],[2.6,.4,1.3],mats.dark,[0,Math.random()*.2,0])}}}
 for(let i=0;i<54;i++){const a=Math.random()*Math.PI*2,r=14+Math.random()*105,x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x,z)<13)continue;const s=.4+Math.random()*1.5;addRock(x,z,s);if(i%4===0)makeCrystalPlant(x+1.3,z+1)} }
function makeCrystalPlant(x,z){const g=group(scene,[x,heightAt(x,z),z]);for(let j=0;j<3;j++){const h=.5+Math.random()*1.25,c=makeMesh(new THREE.OctahedronGeometry(.2+Math.random()*.2),j===0?mats.amber:mats.mint,g,[(Math.random()-.5)*.7,h/2,(Math.random()-.5)*.7],[.1,Math.random(),.15]);c.scale.y=h*2}return g}
