 const x=-9,z=-9;const g=group(scene,[x,heightAt(x,z),z]);box(g,[0,.28,0],[13,.55,10],mats.dark);for(let i=0;i<4;i++){const xx=(i%2)*5-2.5,zz=Math.floor(i/2)*4-2;box(g,[xx,2,zz],[3.1,3.4,2.7],i%2?mats.rust:mats.stone,[0,.12*(i-1),0]);box(g,[xx,3.9,zz],[4,.45,3.4],mats.dark,[0,.12*(i-1),.09]);box(g,[xx,1.2,zz+1.37],[.65,1.6,.08],mats.black)}for(let i=0;i<4;i++){const a=i*1.57;makeMesh(new THREE.CylinderGeometry(.3,.4,3.7,6),mats.pale,g,[Math.cos(a)*7,1.8,Math.sin(a)*5])}const beacon=makeMesh(new THREE.OctahedronGeometry(.55),mats.amber,g,[0,4.8,0]);beacon.userData.pulse=true;return g}
function makePlayer(){const root=group(scene,[state.x,heightAt(state.x,state.z),state.z]);root.name='Nara';const torso=group(root,[0,0,0]);makeMesh(new THREE.CapsuleGeometry(.43,.68,4,8),mats.player,torso,[0,1.25,0]);makeMesh(new THREE.SphereGeometry(.31,10,8),mats.skin,torso,[0,2.02,.04]);makeMesh(new THREE.SphereGeometry(.34,8,6),mats.dark,torso,[0,2.15,0]).scale.set(1,.7,1);box(torso,[0,1.42,-.42],[.6,.76,.15],mats.rust,[.1,0,0]);for(const side of [-1,1]){makeMesh(new THREE.CapsuleGeometry(.13,.5,3,6),mats.player,torso,[side*.51,1.25,0],[0,0,side*.1]);makeMesh(new THREE.CapsuleGeometry(.16,.56,3,6),mats.cloth,torso,[side*.22,.48,0])}const pack=box(torso,[0,1.5,.36],[.48,.65,.26],mats.rust);weapon=group(torso,[.5,1.35,-.12]);box(weapon,[0,0,0],[.09,.12,1.18],mats.amber,[.28,0,-.18]);makeMesh(new THREE.TorusGeometry(.09,.035,6,12),mats.dark,weapon,[0,0,.13],[Math.PI/2,0,0]);const glow=makeMesh(new THREE.SphereGeometry(.12,8,8),mats.mint,torso,[0,1.83,-.44]);glow.userData.pulse=true;return {root,torso,glow}}
function makeNpc(){const root=group(scene,[-9,heightAt(-9,-7),-7]);makeMesh(new THREE.CapsuleGeometry(.37,.65,4,8),mats.npc,root,[0,1.1,0]);makeMesh(new THREE.SphereGeometry(.28,10,8),mat(0xc39570),root,[0,1.86,0]);makeMesh(new THREE.CylinderGeometry(.05,.46,.5,6),mats.dark,root,[0,2.05,0]);box(root,[.42,1.15,0],[.5,.72,.44],mats.amber,[0,0,.1]);makeMesh(new THREE.OctahedronGeometry(.19),mats.mint,root,[0,2.55,0]);root.userData={type:'npc',name:'Sera Ilyan'};npcs.push(root);return root}
function makeEnemy(x,z,type='mireling'){const root=group(scene,[x,heightAt(x,z),z]);root.userData={type:'enemy',kind:type,hp:type==='wisp' ? 42:65,max:type==='wisp'?42:65,speed:type==='wisp'?2.9:1.75,attack:0,dead:false,phase:Math.random()*6};if(type==='wisp'){const core=makeMesh(new THREE.IcosahedronGeometry(.7,1),mat(0x435c5d,.35,0x3a9d8e,.6),root,[0,1.2,0]);const eye=makeMesh(new THREE.SphereGeometry(.17,10,8),mats.eye,root,[0,1.22,.62]);for(let i=0;i<3;i++){makeMesh(new THREE.TorusGeometry(.72+i*.2,.04,5,16),i===1?mats.amber:mats.mint,root,[0,1.2,0],[Math.PI/2,i*.7,0])}root.userData.float=true;}else{makeMesh(new THREE.DodecahedronGeometry(.7,1),mats.enemy,root,[0,1.05,0]).scale.set(1.25,.78,1);makeMesh(new THREE.SphereGeometry(.39,10,8),mats.enemy,root,[0,1.35,.49]);for(let s of [-1,1]){makeMesh(new THREE.ConeGeometry(.15,.55,5),mats.rust,root,[s*.23,1.71,.56],[s*.38,0,s*.35]);makeMesh(new THREE.SphereGeometry(.085,8,8),mats.eye,root,[s*.19,1.39,.83]);makeMesh(new THREE.CylinderGeometry(.1,.14,.6,5),mats.enemy,root,[s*.85,.68,0],[0,0,s*.3])}for(let i=0;i<3;i++)makeMesh(new THREE.ConeGeometry(.12,.46,5),mats.rust,root,[-.3+i*.3,1.58,-.35],[.35,0,Math.PI])}const ring=makeMesh(new THREE.TorusGeometry(.78,.035,5,20),mats.eye,root,[0,.12,0],[Math.PI/2,0,0]);ring.userData.noHit=true;enemies.push(root);return root}
function buildWorld(){scene=new THREE.Scene();scene.background=new THREE.Color(0x87908a);scene.fog=new THREE.FogExp2(0x747e78,.0055);camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,.1,420);renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;ambient=new THREE.HemisphereLight(0xc6ddd3,0x343b35,1.5);scene.add(ambient);dayLight=new THREE.DirectionalLight(0xffdfb1,2.2);dayLight.position.set(-38,65,20);dayLight.castShadow=true;dayLight.shadow.mapSize.set(1024,1024);dayLight.shadow.camera.left=-55;dayLight.shadow.camera.right=55;dayLight.shadow.camera.top=55;dayLight.shadow.camera.bottom=-55;scene.add(dayLight);moonLight=new THREE.DirectionalLight(0x8dd3ca,.15);moonLight.position.set(20,25,-35);scene.add(moonLight);makeTerrain();buildRuins();buildVillage();buildTower(28,3);for(let i=0;i<28;i++){const a=i*2.4,r=22+Math.random()*92,x=Math.cos(a)*r,z=Math.sin(a)*r;makeTree(x,z)}playerModel=makePlayer();makeNpc();makeEnemy(8,3);makeEnemy(12,9);makeEnemy(-24,17,'wisp');makeEnemy(44,0,'wisp');makeEnemy(38,11);makeCaches();makeSky();clock3=new THREE.Clock();}
function makeSky(){const dome=makeMesh(new THREE.SphereGeometry(160,32,20),new THREE.MeshBasicMaterial({color:0x18272c,side:THREE.BackSide}),scene,[0,-6,0]);dome.material.depthWrite=false;const eclipse=makeMesh(new THREE.SphereGeometry(17,32,24),new THREE.MeshBasicMaterial({color:0x0b1216}),scene,[0,68,-125]);const rim=makeMesh(new THREE.TorusGeometry(18,.45,10,64),new THREE.MeshBasicMaterial({color:0x899f98}),scene,[0,68,-125],[0,0,0]);const halo=makeMesh(new THREE.TorusGeometry(22,.08,4,80),new THREE.MeshBasicMaterial({color:0x789b91,transparent:true,opacity:.38}),scene,[0,68,-125]);}
function makeCaches(){const positions=[[-18,-20],[19,-27],[48,17],[-52,-36],[73,-12]];positions.forEach((p,i)=>{const root=group(scene,[p[0],heightAt(...p),p[1]]);box(root,[0,.45,0],[1,.8,.8],i%2?mats.rust:mats.dark,[0,.1,0]);box(root,[0,.88,0],[1.1,.14,.9],mats.amber,[0,.1,0]);makeMesh(new THREE.OctahedronGeometry(.15),mats.mint,root,[0,1.2,0]);root.userData={type:'cache',opened:false,id:i};pickups.push(root)})}
function showToast(text,duration=2500){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),duration)}
function flash(){ui.flash.classList.remove('active');void ui.flash.offsetWidth;ui.flash.classList.add('active')}
function updateHUD(){ui.health.style.width=`${Math.max(0,state.health/state.maxHealth*100)}%`;ui.energy.style.width=`${state.energy/state.maxEnergy*100}%`;ui.food.style.width=`${state.food}%`;ui.xp.style.width=`${state.xp/100*100}%`;ui.healthText.textContent=Math.ceil(state.health);ui.energyText.textContent=Math.floor(state.energy);ui.foodText.textContent=Math.floor(state.food);ui.xpText.textContent=`${state.xp} / 100 XP`;ui.level.textContent=String(state.level).padStart(2,'0');ui.rep.textContent=`VÍNCULO ${state.rep}`;ui.medkits.textContent=state.medkits;ui.threatCount.textContent=enemies.filter(e=>!e.userData.dead&&e.position.distanceTo(player.position)<26).length;ui.threat.classList.toggle('quiet',Number(ui.threatCount.textContent)===0);ui.coords.textContent=`X ${String(Math.round(player.position.x+70)).padStart(3,'0')} · Y ${String(Math.round(player.position.z+70)).padStart(3,'0')}`;ui.questBar.style.width=`${questProgress*100}%`;ui.questLabel.textContent=questStage===0?'0 / 1':questStage===1?'1 / 1':'CONCLUÍDA';}
function gainXP(n){state.xp+=n;while(state.xp>=100){state.xp-=100;state.level++;state.maxHealth+=10;state.health=Math.min(state.maxHealth,state.health+25);state.maxEnergy+=8;state.energy=state.maxEnergy;flash();showToast(`NÍVEL ${state.level} · NOVA SINTONIA DISPONÍVEL`,3000);if(state.level>=2){state.anchorUnlocked=true;$('#ability-r').classList.remove('locked');$('#ability-r').querySelector('small').textContent='24 EN'}if(state.level>=3){state.arcUnlocked=true;$('#ability-c').classList.remove('locked');$('#ability-c').querySelector('small').textContent='28 EN'}}updateHUD();saveGame()}
function showModal(kicker,title,body,options=[]){modalOpen=true;ui.modal.innerHTML=`<button class="modal-close" aria-label="Fechar">×</button><div class="modal-kicker">${kicker}</div><h1>${title}</h1><p>${body}</p>${options.length?`<div class="modal-row">${options.map(o=>`<button class="${o.class||'choice-button'}" data-action="${o.action}">${o.html}</button>`).join('')}</div>`:''}`;ui.backdrop.classList.add('open');ui.modal.querySelector('.modal-close').onclick=closeModal;ui.modal.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));}
function closeModal(){ui.backdrop.classList.remove('open');modalOpen=false;}
function handleAction(action){if(action==='sera-talk'){closeModal();openSera()}else if(action==='sera-repair'){state.rep+=2;state.inventory['Erva-luz']=(state.inventory['Erva-luz']||0)+1;state.inventory['Fibra de névoa']=(state.inventory['Fibra de névoa']||0)+2;showToast('SERA CONFIARÁ MAIS EM VOCÊ · +2 VÍNCULO');closeModal();saveGame();updateHUD()}else if(action==='sera-map'){state.rep++;showModal('SERA ILYAN · CARTÓGRAFA','O mapa não termina aqui.','Sera marca três ruínas no seu visor. “A gente sobrevive melhor quando sabe o nome das coisas.” Você sente que ela guarda algo sobre a noite em que chegou ao vale.',[{action:'close',class:'modal-button',html:'ENTENDI'}])}else if(action==='discover'){discoverTower()}else if(action==='broadcast'||action==='silence'){state.decision=action;state.rep+=action==='broadcast'?3:-1;questStage=2;questProgress=1;state.inventory['Fragmento âmbar']=(state.inventory['Fragmento âmbar']||0)+3;gainXP(55);showModal('DECISÃO REGISTRADA',action==='broadcast'?'UMA LUZ PARA OS PERDIDOS':'UM SEGREDO PRESERVADO',action==='broadcast'?'O sinal atravessa o vale. Em algum lugar, três luzes respondem — e a coluna escura no céu parece estremecer. Sera sabe que você os expôs ao perigo, mas não consegue esconder o alívio.':'Você dobra o pulso para dentro da pedra. O sinal se cala; por um instante, algo enorme se move sob o chão. Sera não discute, mas seu silêncio pesa. O horizonte continua fechado.',[{action:'close',class:'modal-button',html:'CONTINUAR'}]);updateQuest();saveGame()}else if(action==='inventory'){openInventory()}else if(action==='skills'){openSkills()}else if(action==='map'){openMap()}else if(action==='rest'){closeModal();if(state.food<10){showToast('SEM PROVISÕES PARA ACAMPAR');return}state.food-=10;state.health=Math.min(state.maxHealth,state.health+35);state.energy=state.maxEnergy;worldTime=(worldTime+7.5)%24;showToast('DESCANSO CONCLUÍDO · +35 SAÚDE');updateHUD()}else if(action==='craft'){if((state.inventory['Erva-luz']||0)>=1&&(state.inventory['Fibra de névoa']||0)>=1){state.inventory['Erva-luz']--;state.inventory['Fibra de névoa']--;state.medkits++;showToast('KIT VITAL FABRICADO');openInventory()}else showToast('PRECISA DE 1 ERVA-LUZ + 1 FIBRA')}else if(action==='close')closeModal()}
function openSera(){const first=!state.seen.sera;state.seen.sera=true;showModal('DUSKLINE · VÍNCULO '+state.rep,first?'Sera Ilyan':'Sera lembra de você',first?'A cartógrafa limpa a poeira de uma lente rachada. “Nara, certo? O vale inteiro vibrou quando você tocou aquele fragmento. A torre caída acordou. Eu ouvi algo lá dentro — uma voz contando até zero.”':'“O céu não é uma tampa, Nara. É uma pergunta. Talvez lá na torre encontremos quem está tentando responder.”',[{action:'sera-map',html:'<b>“O que você sabe sobre o Eclipse?”</b><small>Conheça a história de Sera</small>'},{action:'sera-repair',html:'<b>“Trouxe material para os filtros.”</b><small>Receber erva-luz e fibra · +2 vínculo</small>'},{action:'close',html:'<b>“Preciso seguir o sinal.”</b><small>Encerrar conversa</small>'}]);}
function discoverTower(){if(questStage>0){showModal('CORAÇÃO DO VALE','A câmara está em silêncio','O fragmento reconhece sua presença. Você já tomou sua decisão. Ainda há sinais para seguir além das ruínas.',[{action:'close',class:'modal-button',html:'VOLTAR AO VALE'}]);return}questStage=1;questProgress=1;updateQuest();showModal('SINAL IDENTIFICADO · TORRE 01','A memória que não era sua', 'O núcleo se abre como uma flor de vidro. Não há voz, apenas uma lembrança gravada em luz: o Eclipse não caiu do céu. Foi construído — uma máquina para esconder a humanidade de algo que ainda procura por ela. O fragmento pode transmitir o sinal ou mantê-lo aqui.',[{action:'broadcast',html:'<b>ACENDER O SINAL</b><small>Reunir sobreviventes · +3 vínculo com Duskline</small>'},{action:'silence',html:'<b>GUARDAR O SEGREDO</b><small>Proteger o assentamento · menos confiança</small>'}]);}
function updateQuest(){if(questStage===0){ui.questTitle.textContent='O eco sob as ruínas';ui.questDesc.textContent='Encontre a origem do pulso na torre caída.'}else if(questStage===1){ui.questTitle.textContent='Uma escolha, dois horizontes';ui.questDesc.textContent='Decida o que fazer com o sinal do núcleo.'}else{ui.questTitle.textContent=state.decision==='broadcast'?'Uma luz no horizonte':'O silêncio sob as cinzas';ui.questDesc.textContent=state.decision==='broadcast'?'Três sinais responderam. Encontre quem os enviou.':'A máquina ainda respira sob o vale.'}}
function openInventory(){const entries=Object.entries(state.inventory);showModal('NARA VENN · CARGA','Inventário & sobrevivência','Recursos coletados no vale. Fabrique kit vitais com erva-luz e fibra de névoa.',[]);ui.modal.insertAdjacentHTML('beforeend',`<div class="inventory-grid">${entries.map(([n,c])=>`<div class="inventory-item"><b>${n}</b><small>QUANTIDADE · ${c}</small></div>`).join('')}<div class="inventory-item"><b>Kit vital</b><small>QUANTIDADE · ${state.medkits}</small></div><div class="inventory-item"><b>Fragmentos de ressonância</b><small>QUANTIDADE · ${state.shards}</small></div></div><div class="modal-row"><button class="modal-button" data-action="craft">FABRICAR KIT VITAL</button><button class="modal-button" data-action="rest">ACAMPAR · RECUPERAR</button></div>`);ui.modal.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action))}
function openSkills(){const skills=[['Fenda','Q · Arranco espacial','Cruza 8 m num piscar. Invulnerabilidade curta. Custa 12 energia.'],['Pulso de retorno','E · Onda de impacto','Dano em área, quebra a postura e absorve ecos. Custa 20 energia.'],['Âncora de maré','R · Desbloqueio nível 2','Prende criaturas numa gravidade dobrada por 3 s. Custa 24 energia.'],['Arco refrator','C · Desbloqueio nível 3','Projétil ricocheteia entre inimigos próximos. Custa 28 energia.']];showModal('RESSONÂNCIA · ÁRVORE DE SINTONIA','Seus poderes não são armas.', 'Fragmentos do Eclipse se alinham à sua intenção. Evolua enfrentando criaturas e descobrindo a história do vale.',[]);ui.modal.insertAdjacentHTML('beforeend',`<div class="skill-list">${skills.map((s,i)=>`<div class="skill-item" style="opacity:${i===2&&!state.anchorUnlocked||i===3&&!state.arcUnlocked?.45:1}"><b>${s[0]} ${i===2&&!state.anchorUnlocked?'· BLOQUEADO LV 2':i===3&&!state.arcUnlocked?'· BLOQUEADO LV 3':''}</b><small>${s[1]}<br>${s[2]}</small></div>`).join('')}</div><div class="modal-row"><button class="modal-button" data-action="close">FECHAR</button></div>`);ui.modal.querySelectorAll('[data-action]').forEach(b=>b.onclick=closeModal)}
function openMap(){showModal('CARTOGRAFIA DE SERA · SETOR 07','Vale das Cinzas','Duskline fica ao sudoeste. A torre antiga pulsa a leste. O mapa se revela conforme você explora.',[]);ui.modal.insertAdjacentHTML('beforeend','<div style="height:180px;margin-top:16px;position:relative;overflow:hidden;border:1px solid #d5f0e425;background:radial-gradient(ellipse,#65706a,#263634)"><div style="position:absolute;inset:0;background-image:linear-gradient(#c0e0d51c 1px,transparent 1px),linear-gradient(90deg,#c0e0d51c 1px,transparent 1px);background-size:35px 35px"></div><span style="position:absolute;left:36%;top:58%;color:#e8c37e">◆ DUSKLINE</span><span style="position:absolute;left:74%;top:24%;color:#9ae6cf">◎ TORRE 01</span><span style="position:absolute;left:52%;top:51%;color:white">▲ VOCÊ</span></div><div class="modal-row"><button class="modal-button" data-action="close">VOLTAR AO VALE</button></div>');ui.modal.querySelectorAll('[data-action]').forEach(b=>b.onclick=closeModal)}
function openMenu(){showModal('PAUSA · ECLIPSE','O último horizonte','Sobreviva ao vale. Seu progresso fica salvo neste dispositivo.',[{action:'inventory',html:'<b>INVENTÁRIO</b><small>Recursos e kits vitais</small>'},{action:'skills',html:'<b>SINTONIA</b><small>Conheça poderes e evoluções</small>'},{action:'map',html:'<b>MAPA DO VALE</b><small>Veja seus destinos conhecidos</small>'},{action:'close',class:'modal-button',html:'RETOMAR EXPLORAÇÃO'}])}
function attack(){if(modalOpen||attackTimer>0)return;attackTimer=.38;playerModel.torso.rotation.x=-.25;weapon.rotation.x=-1.1;weapon.rotation.z=-.4;const forward=V(Math.sin(playerModel.root.rotation.y),0,Math.cos(playerModel.root.rotation.y));let hit=0;for(const e of enemies){const d=e.position.clone().sub(player.position);const distance=d.length();d.y=0;const facing=d.normalize().dot(forward);if(!e.userData.dead&&distance<3.6&&facing>.05){damageEnemy(e,32+(state.level-1)*4);hit++}}if(hit){state.energy=Math.min(state.maxEnergy,state.energy+7);flash()}spawnSlash(player.position.clone().add(forward.clone().multiplyScalar(1.4)).add(V(0,1,0)),forward);}
function damageEnemy(e,amount){const u=e.userData;if(u.dead)return;u.hp-=amount;e.userData.hit=.18;spawnBurst(e.position.clone().add(V(0,1,0)),0x91e8cf,7);if(u.hp<=0){u.dead=true;state.kills++;state.shards+=u.kind==='wisp'?2:1;state.inventory['Fragmento âmbar']=(state.inventory['Fragmento âmbar']||0)+1;gainXP(u.kind==='wisp'?38:28);showToast(u.kind==='wisp'?'ECO DISSOLVIDO · +2 FRAGMENTOS':'MIRELING ABATIDO · +1 FRAGMENTO');setTimeout(()=>{if(e.parent)e.parent.remove(e);enemies=enemies.filter(x=>x!==e)},420);updateHUD();saveGame()}}
function usePower(type){if(modalOpen)return;if(type==='r'&&!state.anchorUnlocked||type==='c'&&!state.arcUnlocked)return;const cost={q:12,e:20,r:24,c:28}[type];if(abilityCooldown[type]>0)return;if(state.energy<cost){showToast('ENERGIA INSUFICIENTE');return}state.energy-=cost;abilityCooldown[type]={q:3.3,e:5.7,r:9,c:7.5}[type];const btn=$(`#ability-${type}`);btn.classList.add('on-cooldown');if(type==='q'){const dir=V(Math.sin(playerModel.root.rotation.y),0,Math.cos(playerModel.root.rotation.y));const old=player.position.clone();player.position.add(dir.multiplyScalar(8));player.position.x=THREE.MathUtils.clamp(player.position.x,-125,125);player.position.z=THREE.MathUtils.clamp(player.position.z,-125,125);spawnBurst(old.add(V(0,1,0)),0x8cebd1,18);spawnBurst(player.position.clone().add(V(0,1,0)),0x8cebd1,18);flash();}if(type==='e'){const center=player.position.clone();spawnRing(center.clone().add(V(0,.35,0)),0xa0f0d7,1);for(const e of enemies)if(!e.userData.dead&&e.position.distanceTo(center)<7){damageEnemy(e,39+(state.level-1)*5);e.userData.stun=.9}flash();}if(type==='r'){const targets=enemies.filter(e=>!e.userData.dead&&e.position.distanceTo(player.position)<13);for(const e of targets){e.userData.stun=3;spawnRing(e.position.clone().add(V(0,.15,0)),0x99deff,.55)}showToast(targets.length?'ÂNCORA DE MARÉ · ALVOS PRESOS':'ÂNCORA DE MARÉ · SEM ALVOS');}if(type==='c'){const targets=enemies.filter(e=>!e.userData.dead&&e.position.distanceTo(player.position)<22).sort((a,b)=>a.position.distanceTo(player.position)-b.position.distanceTo(player.position)).slice(0,3);if(targets.length){targets.forEach((e,i)=>setTimeout(()=>{if(e.parent&&!e.userData.dead){damageEnemy(e,34);spawnBolt(player.position.clone().add(V(0,1.6,0)),e.position.clone().add(V(0,1,0)))}},i*170))}else showToast('ARCO REFRATOR · SEM ALVOS');}updateHUD()}
function spawnSlash(pos,dir){const g=makeMesh(new THREE.TorusGeometry(1.05,.07,6,22,Math.PI*1.3),mats.amber,scene,pos,[Math.PI/2,0,-Math.atan2(dir.x,dir.z)]);g.userData={life:.3,particle:true,scaleOut:true};particles.push(g)}
function spawnRing(pos,color,size){const material=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8});const m=makeMesh(new THREE.TorusGeometry(size,.07,6,28),material,scene,pos,[Math.PI/2,0,0]);m.userData={life:.55,particle:true,scaleOut:true};particles.push(m)}
function spawnBurst(pos,color,count=10){for(let i=0;i<count;i++){const m=makeMesh(new THREE.IcosahedronGeometry(.06+Math.random()*.09),new THREE.MeshBasicMaterial({color,transparent:true}),scene,pos.toArray());m.userData={life:.35+Math.random()*.4,particle:true,velocity:V((Math.random()-.5)*6,Math.random()*5,(Math.random()-.5)*6)};particles.push(m)}}
function spawnBolt(a,b){const mid=a.clone().add(b).multiplyScalar(.5);const geo=new THREE.BufferGeometry().setFromPoints([a,b]);const line=new THREE.Line(geo,new THREE.LineBasicMaterial({color:0xa1ffe0,transparent:true,opacity:.95}));scene.add(line);line.userData={life:.18,particle:true,bolt:true};particles.push(line);spawnBurst(b,0x9dffe2,4)}
function useMedkit(){if(state.medkits<1){showToast('SEM KIT VITAL · FABRIQUE NO INVENTÁRIO');return}if(state.health>=state.maxHealth){showToast('SAÚDE JÁ ESTÁ COMPLETA');return}state.medkits--;state.health=Math.min(state.maxHealth,state.health+40);state.food=Math.max(0,state.food-2);flash();showToast('KIT VITAL · +40 SAÚDE');updateHUD();saveGame()}
function interact(){if(!nearby)return;const o=nearby;if(o.userData.type==='npc')openSera();else if(o.userData.type==='objective')discoverTower();else if(o.userData.type==='cache'){if(o.userData.opened){showToast('ESTOJO JÁ VASCULHADO');return}o.userData.opened=true;state.found++;state.inventory['Fragmento âmbar']=(state.inventory['Fragmento âmbar']||0)+2;state.inventory['Fibra de névoa']=(state.inventory['Fibra de névoa']||0)+1;state.inventory['Erva-luz']=(state.inventory['Erva-luz']||0)+1;if(Math.random()<.55)state.medkits++;gainXP(18);o.rotation.x=-1.1;showToast('ESTOJO ABERTO · ÂMBAR, FIBRA E ERVA-LUZ');updateHUD();saveGame()}}
function saveGame(){try{const data={...state,seen:state.seen,questStage,decision:state.decision};localStorage.setItem('eclipse-save',JSON.stringify(data))}catch{}}
function loadGame(){try{const s=JSON.parse(localStorage.getItem('eclipse-save')||'null');if(s){Object.assign(state,s);questStage=s.questStage||0;state.decision=s.decision||'';if(state.level>=2){state.anchorUnlocked=true;$('#ability-r').classList.remove('locked');$('#ability-r').querySelector('small').textContent='24 EN'}if(state.level>=3){state.arcUnlocked=true;$('#ability-c').classList.remove('locked');$('#ability-c').querySelector('small').textContent='28 EN'}}}catch{}updateQuest()}
function findNearby(){let best=null,dist=4.4;for(const obj of [...npcs,...pickups,world.tower]){if(!obj||obj.userData.type==='cache'&&obj.userData.opened)continue;const d=player.position.distanceTo(obj.position);if(d<dist){best=obj;dist=d}}nearby=best;if(best){ui.interaction.classList.add('visible');ui.hint.classList.add('visible');ui.interactionText.textContent=best.userData.type==='npc'?'FALAR · SERA ILYAN':best.userData.type==='objective'?'TOCAR NO NÚCLEO':best.userData.type==='cache'?'VASCULHAR ESTOJO':'INTERAGIR';ui.hint.innerHTML=`<span>F</span> ${ui.interactionText.textContent}`}else{ui.interaction.classList.remove('visible');ui.hint.classList.remove('visible')}}
function updatePlayer(dt){let inputX=0,inputZ=0;if(keys.KeyW||keys.ArrowUp)inputZ-=1;if(keys.KeyS||keys.ArrowDown)inputZ+=1;if(keys.KeyA||keys.ArrowLeft)inputX-=1;if(keys.KeyD||keys.ArrowRight)inputX+=1;inputX+=touchInput.x;inputZ+=touchInput.y;const v=V(inputX,0,inputZ);if(v.length()>1)v.normalize();const speed=(keys.ShiftLeft||keys.ShiftRight?9.8:6.3)*(state.food<=0?.75:1);const worldDir=V(v.x*Math.cos(camYaw)-v.z*Math.sin(camYaw),0,v.x*Math.sin(camYaw)+v.z*Math.cos(camYaw));player.position.x+=worldDir.x*speed*dt;player.position.z+=worldDir.z*speed*dt;player.position.x=THREE.MathUtils.clamp(player.position.x,-127,127);player.position.z=THREE.MathUtils.clamp(player.position.z,-127,127);player.position.y=heightAt(player.position.x,player.position.z);playerModel.root.position.copy(player.position);if(v.lengthSq()>.02){const angle=Math.atan2(worldDir.x,worldDir.z);playerModel.root.rotation.y=angle;playerModel.torso.position.y=.045*Math.sin(worldTime*8);weapon.rotation.x=THREE.MathUtils.lerp(weapon.rotation.x,0,dt*9);weapon.rotation.z=THREE.MathUtils.lerp(weapon.rotation.z,0,dt*9)}else playerModel.torso.position.y=THREE.MathUtils.lerp(playerModel.torso.position.y,0,dt*8);if(attackTimer>0){attackTimer-=dt;if(attackTimer<=0){playerModel.torso.rotation.x=0;weapon.rotation.x=0;weapon.rotation.z=0}}if(keys.Space&&!keys.spaceLock){keys.spaceLock=true;dodge()}if(!keys.Space)keys.spaceLock=false;state.energy=Math.min(state.maxEnergy,state.energy+dt*5.2);state.food=Math.max(0,state.food-dt*.032);}
function dodge(){if(state.energy<8){showToast('ENERGIA INSUFICIENTE');return}state.energy-=8;const dir=V(Math.sin(playerModel.root.rotation.y),0,Math.cos(playerModel.root.rotation.y));if(!keys.KeyW&&!keys.KeyA&&!keys.KeyS&&!keys.KeyD)dir.multiplyScalar(-1);player.position.add(dir.multiplyScalar(4.5));spawnBurst(player.position.clone().add(V(0,1,0)),0x9ae6cf,10);flash()}
function updateEnemies(dt,t){for(const e of enemies){const u=e.userData;if(u.dead)continue;const delta=player.position.clone().sub(e.position);delta.y=0;const distance=delta.length();if(u.float){e.position.y=heightAt(e.position.x,e.position.z)+1.2+Math.sin(t*2+u.phase)*.28;e.rotation.y+=dt*.28}else e.position.y=heightAt(e.position.x,e.position.z);if(u.hit){u.hit-=dt;e.scale.setScalar(1.06)}else e.scale.setScalar(1);if(u.stun>0){u.stun-=dt;e.rotation.z=Math.sin(t*22)*.08;continue}if(distance<31){if(distance>1.8){delta.normalize();const sp=u.speed*(distance<3?0.48:1);e.position.x+=delta.x*sp*dt;e.position.z+=delta.z*sp*dt;if(!u.float)e.rotation.y=Math.atan2(delta.x,delta.z);if(!u.float)e.position.y=heightAt(e.position.x,e.position.z);e.position.x=THREE.MathUtils.clamp(e.position.x,-130,130);e.position.z=THREE.MathUtils.clamp(e.position.z,-130,130)}else{u.attack-=dt;if(u.attack<=0){u.attack=1.35;state.health=Math.max(0,state.health-(u.kind==='wisp'?12:9));damageFlash=.2;showToast(u.kind==='wisp'?'O ECO DRENOU SUA ENERGIA':'VOCÊ FOI FERIDA');if(state.health<=0)knockout()}}}else if(distance>35&&distance<80){e.position.x+=(Math.random()-.5)*dt*.6;e.position.z+=(Math.random()-.5)*dt*.6}}}
function knockout(){state.health=55;state.energy=60;state.food=Math.max(0,state.food-12);player.position.set(-9,heightAt(-9,-9),-9);showModal('CORPO EM REPOUSO','Sera trouxe você de volta.','Você acorda em Duskline, com os ecos ainda zunindo na cabeça. A mochila foi preservada, mas o vale cobrou seu preço.',[{action:'close',class:'modal-button',html:'LEVANTAR'}]);saveGame()}
function updateCamera(dt){const target=player.position.clone().add(V(0,1.25,0));const dist=8.6;const desired=target.clone().add(V(Math.sin(camYaw)*dist,3.1+camPitch*3,Math.cos(camYaw)*dist));camera.position.lerp(desired,1-Math.pow(.001,dt));camera.lookAt(target)}
function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i],u=p.userData;u.life-=dt;if(u.velocity){p.position.addScaledVector(u.velocity,dt);u.velocity.y-=9*dt}if(u.scaleOut){p.scale.multiplyScalar(1+dt*2);if(p.material.opacity!==undefined)p.material.opacity=Math.max(0,u.life*1.6)}if(u.bolt)p.material.opacity=Math.max(0,u.life*5);if(u.life<=0){scene.remove(p);if(p.geometry)p.geometry.dispose();if(p.material)p.material.dispose();particles.splice(i,1)}}}
function updateClock(dt){worldTime=(worldTime+dt*.035)%24;const hour=Math.floor(worldTime+6)%24,minute=Math.floor((worldTime*60)%60);ui.clock.textContent=`${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`;const sun=Math.sin((worldTime/24)*Math.PI*2);const daylight=THREE.MathUtils.clamp((sun+.3)/.95,0,1);dayLight.intensity=.22+daylight*2.2;ambient.intensity=.55+daylight*1.02;moonLight.intensity=.08+(1-daylight)*.55;scene.fog.color.set(daylight>.35?0x747e78:0x273b42);scene.fog.density=.0044+(1-daylight)*.004;renderer.toneMappingExposure=.72+daylight*.42;ui.region.textContent=player.position.length()>72?'BORDA DA NÉVOA':player.position.length()<20?'VALE DAS CINZAS':'RUÍNAS DE LITH';for(const o of scene.children)if(o.userData?.pulse)o.rotation.y+=dt*.5;}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock3.getDelta(),.04),t=clock3.elapsedTime;updatePlayer(dt);updateEnemies(dt,t);updateCamera(dt);findNearby();updateParticles(dt);updateClock(dt);if(damageFlash>0)damageFlash-=dt;for(const [k,v] of Object.entries(abilityCooldown)){if(v>0){abilityCooldown[k]=Math.max(0,v-dt);const b=$(`#ability-${k}`);b.classList.toggle('on-cooldown',abilityCooldown[k]>0);b.dataset.time=abilityCooldown[k].toFixed(1);b.querySelector('.cooldown').style.width=`${abilityCooldown[k]/({q:3.3,e:5.7,r:9,c:7.5}[k])*100}%`}}saveTimer+=dt;if(saveTimer>18){saveTimer=0;saveGame()}updateHUD();renderer.render(scene,camera)}
const touchInput={x:0,y:0};function setupTouch(){const base=$('#joystick'),knob=$('#joy-knob');let id=null,rect;function start(e){e.preventDefault();id=e.pointerId;base.setPointerCapture(id);rect=base.getBoundingClientRect();move(e)}function move(e){if(id!==e.pointerId)return;const cx=rect.left+rect.width/2,cy=rect.top+rect.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=rect.width*.36,d=Math.hypot(dx,dy),mult=Math.min(1,max/d);touchInput.x=dx*mult/max;touchInput.y=dy*mult/max;knob.style.transform=`translate(${touchInput.x*max}px,${touchInput.y*max}px)`}function end(e){if(id!==e.pointerId)return;id=null;touchInput.x=touchInput.y=0;knob.style.transform=''}base.addEventListener('pointerdown',start);base.addEventListener('pointermove',move);base.addEventListener('pointerup',end);base.addEventListener('pointercancel',end);$('#touch-attack').onclick=attack;$('#touch-dodge').onclick=dodge;$('#touch-power').onclick=()=>usePower('e');$('#touch-interact').onclick=interact}
function setup(){loadGame();buildWorld();world={tower:scene.children.find(o=>o.userData?.type==='objective')};if(!world.tower)world.tower=scene.children.find(o=>o.userData?.type==='objective');player=playerModel.root;player.position.set(state.x,heightAt(state.x,state.z),state.z);playerModel.root.position.copy(player.position);camera.position.set(0,7,20);camera.lookAt(0,1,0);$('#ability-q').onclick=()=>usePower('q');$('#ability-e').onclick=()=>usePower('e');$('#ability-r').onclick=()=>usePower('r');$('#ability-c').onclick=()=>usePower('c');$('#use-item').onclick=useMedkit;$('#map-button').onclick=openMap;$('#menu-button').onclick=openMenu;$('#modal-backdrop').addEventListener('click',e=>{if(e.target===ui.backdrop)closeModal()});window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyF')interact();if(e.code==='KeyQ')usePower('q');if(e.code==='KeyE')usePower('e');if(e.code==='KeyR')usePower('r');if(e.code==='KeyC')usePower('c');if(e.code==='Digit1')useMedkit();if(e.code==='KeyI')openInventory();if(e.code==='KeyM')openMap;if(e.code==='Escape'){modalOpen?closeModal():openMenu()}});window.addEventListener('keyup',e=>keys[e.code]=false);canvas.addEventListener('pointerdown',e=>{if(e.button===0&&!e.target.closest('button')){dragging=true;prevPointer={x:e.clientX,y:e.clientY};if(e.pointerType==='mouse')attack()}});window.addEventListener('pointerup',()=>dragging=false);window.addEventListener('pointermove',e=>{if(dragging&&e.pointerType==='mouse'){const dx=e.clientX-prevPointer.x,dy=e.clientY-prevPointer.y;if(Math.abs(dx)+Math.abs(dy)>4){camYaw-=dx*.006;camPitch=THREE.MathUtils.clamp(camPitch-dy*.003,-.1,.65)}prevPointer={x:e.clientX,y:e.clientY}}});canvas.addEventListener('touchstart',e=>{if(e.touches.length===1){prevPointer={x:e.touches[0].clientX,y:e.touches[0].clientY};dragging=true}},{passive:true});canvas.addEventListener('touchmove',e=>{if(dragging&&e.touches.length===1){const t=e.touches[0],dx=t.clientX-prevPointer.x,dy=t.clientY-prevPointer.y;camYaw-=dx*.005;camPitch=THREE.MathUtils.clamp(camPitch-dy*.003,-.1,.65);prevPointer={x:t.clientX,y:t.clientY}}},{passive:true});canvas.addEventListener('touchend',()=>dragging=false);setupTouch();window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});updateHUD();animate()}
try{setup()}catch(err){console.error(err);document.body.insertAdjacentHTML('beforeend',`<div class="loading-error"><div><h1>ECLIPSE</h1><p>Não foi possível iniciar o mundo 3D. Verifique a conexão e recarregue a página.</p><small>${String(err.message||err)}</small></div></div>`)}

